/* @lc app=leetcode id=2127 lang=kotlin */ class Solution { fun up(dep: IntArray, v: Int, x: Int) = x.also { dep[v] = maxOf(dep[v], it) } fun maximumInvitations(favorite: IntArray): Int = favorite.size.let { n -> IntArray(n).also { d -> favorite.forEach { d[it]++ } }.let { d -> IntArray(n).let { dep -> generateSequence((0 until n).filter { d[it] == 0 }) { f -> f.mapNotNull { u -> favorite[u].takeIf { v -> up(dep, v, dep[u] + 1).let { --d[v] == 0 } } }.takeIf { it.isNotEmpty() } }.count().let { (0 until n).filter { d[it] > 0 }.let { cyc -> BooleanArray(n).let { seen -> cyc.fold(0 to 0) { (mx, pairs), i -> if (seen[i]) mx to pairs else generateSequence(i) { favorite[it].takeIf { v -> v != i } }.onEach { seen[it] = true }.count().let { len -> if (len == 2) mx to pairs + dep[i] + dep[favorite[i]] + 2 else maxOf(mx, len) to pairs } }.let { (mx, pairs) -> maxOf(mx, pairs) } } } } } } } }